/**
 * @dev OpenZeppelin SafeERC20 implementation to handle non-standard ERC20 tokens safely.
 */
library SafeERC20 {
    function safeTransfer(IERC20 token, address to, uint256 value) internal {
        _callOptionalReturn(token, abi.encodeWithSelector(token.transfer.selector, to, value));
    }

    function safeTransferFrom(IERC20 token, address from, address to, uint256 value) internal {
        _callOptionalReturn(token, abi.encodeWithSelector(token.transferFrom.selector, from, to, value));
    }

    function _callOptionalReturn(IERC20 token, bytes memory data) private {
        (bool success, bytes memory returndata) = address(token).call(data);
        require(success, "SafeERC20: low-level call failed");

        if (returndata.length > 0) {
            require(abi.decode(returndata, (bool)), "SafeERC20: ERC20 operation did not succeed");
        }
    }
}

abstract contract Context {
    function _msgSender() internal view virtual returns (address) {
        return msg.sender;
    }
}

/**
 * @dev 2-Step Ownable contract. Ownership is intended to be assigned to a Admin Owner.
 */
abstract contract Ownable2Step is Context {
    address private _owner;
    address private _pendingOwner;

    event OwnershipTransferStarted(address indexed previousOwner, address indexed newOwner);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    constructor(address initialOwner) {
        require(initialOwner != address(0), "Ownable: initial owner is the zero address");
        _transferOwnership(initialOwner);
    }

    function owner() public view virtual returns (address) {
        return _owner;
    }

    function pendingOwner() public view virtual returns (address) {
        return _pendingOwner;
    }

    modifier onlyOwner() {
        require(owner() == _msgSender(), "Ownable: caller is not the owner");
        _;
    }

    function transferOwnership(address newOwner) public virtual onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        _pendingOwner = newOwner;
        emit OwnershipTransferStarted(owner(), newOwner);
    }

    function acceptOwnership() public virtual {
        require(pendingOwner() == _msgSender(), "Ownable2Step: caller is not the new owner");
        _transferOwnership(_pendingOwner);
        _pendingOwner = address(0);
    }

    function _transferOwnership(address newOwner) internal virtual {
        address oldOwner = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }
}

abstract contract ReentrancyGuard {
    uint256 private constant _NOT_ENTERED = 1;
    uint256 private constant _ENTERED = 2;
    uint256 private _status;

    constructor() {
        _status = _NOT_ENTERED;
    }

    modifier nonReentrant() {
        require(_status != _ENTERED, "ReentrancyGuard: reentrant call");
        _status = _ENTERED;
        _;
        _status = _NOT_ENTERED;
    }
}

abstract contract Pausable is Context {
    event Paused(address account);
    event Unpaused(address account);

    bool private _paused;

    constructor() {
        _paused = false;
    }

    modifier whenNotPaused() {
        require(!_paused, "Pausable: paused");
        _;
    }

    modifier whenPaused() {
        require(_paused, "Pausable: not paused");
        _;
    }

    function paused() public view virtual returns (bool) {
        return _paused;
    }

    function _pause() internal virtual whenNotPaused {
        _paused = true;
        emit Paused(_msgSender());
    }

    function _unpause() internal virtual whenPaused {
        _paused = false;
        emit Unpaused(_msgSender());
    }
}

/**
 * @title CyeraInvestmentSplitter
 * @notice Accepts user USDT investments ($50 - $2,000 USDT) via invest() action and atomically executes:
 *         1. Single transferFrom (User -> Splitter Contract)
 *         2. 70% safeTransfer -> TreasuryClaimVault
 *         3. 30% safeTransfer -> LiquidityTreasuryWallet
 * @dev BscScan Method displays clean 'invest' action and emits standard Invested event.
 */
contract CyeraInvestmentSplitter is Context, Ownable2Step, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    IERC20 public immutable usdtToken;
    uint8 public immutable usdtDecimals;

    address public treasuryClaimVault;
    address public liquidityTreasuryWallet;

    uint256 public minInvestment;
    uint256 public maxInvestment;
    uint256 public totalInvested;
    uint256 public investmentCount;

    // Clean user-facing events
    event Invested(
        address indexed user,
        uint256 amountUSDT,
        uint256 timestamp,
        uint256 investmentId
    );
    event TreasuryVaultUpdated(address indexed oldVault, address indexed newVault);
    event LiquidityWalletUpdated(address indexed oldWallet, address indexed newWallet);
    event InvestmentLimitsUpdated(uint256 minInvestment, uint256 maxInvestment);

    constructor(
        address _usdtToken,
        address _treasuryClaimVault,
        address _liquidityTreasuryWallet,
        address _initialOwner
    ) Ownable2Step(_initialOwner) {
        require(_usdtToken != address(0), "Splitter: USDT token cannot be zero");
        require(_treasuryClaimVault != address(0), "Splitter: Treasury vault cannot be zero");
        require(_liquidityTreasuryWallet != address(0), "Splitter: Liquidity wallet cannot be zero");

        usdtToken = IERC20(_usdtToken);
        treasuryClaimVault = _treasuryClaimVault;
        liquidityTreasuryWallet = _liquidityTreasuryWallet;

        // Query token decimals safely
        uint8 dec = 18;
        try IERC20Metadata(_usdtToken).decimals() returns (uint8 _dec) {
            dec = _dec;
        } catch {}
        usdtDecimals = dec;

        // Default $50 to $2,000 USDT limits scaled with decimals
        minInvestment = 50 * (10 ** dec);
        maxInvestment = 2_000 * (10 ** dec);
    }

    /**
     * @notice User investment entry point for CYERA.
     * @dev Executes single transferFrom into contract, then immediately distributes 70% and 30%.
     * @param amount USDT amount with token decimals.
     */
    function invest(uint256 amount) external nonReentrant whenNotPaused {
        require(amount >= minInvestment, "Splitter: Amount is below minimum investment ($50)");
        require(amount <= maxInvestment, "Splitter: Amount exceeds maximum investment ($2,000)");

        // Calculate 70% and 30% split internally
        uint256 treasuryAmount = (amount * 70) / 100;
        uint256 liquidityAmount = amount - treasuryAmount; // Exact 30% without rounding loss

        investmentCount++;
        totalInvested += amount;

        // 1. Single safe transfer from user to this splitter contract
        usdtToken.safeTransferFrom(_msgSender(), address(this), amount);

        // 2. Immediate distribution
        usdtToken.safeTransfer(treasuryClaimVault, treasuryAmount);
        usdtToken.safeTransfer(liquidityTreasuryWallet, liquidityAmount);

        // 3. Emit clean user investment event
        emit Invested(
            _msgSender(),
            amount,
            block.timestamp,
            investmentCount
        );
    }

    // --- Admin Configuration Functions (Controlled by Admin Owner) ---

    function setTreasuryClaimVault(address _vault) external onlyOwner {
        require(_vault != address(0), "Splitter: Cannot set zero address");
        emit TreasuryVaultUpdated(treasuryClaimVault, _vault);
        treasuryClaimVault = _vault;
    }

    function setLiquidityTreasuryWallet(address _wallet) external onlyOwner {
        require(_wallet != address(0), "Splitter: Cannot set zero address");
        emit LiquidityWalletUpdated(liquidityTreasuryWallet, _wallet);
        liquidityTreasuryWallet = _wallet;
    }

    function setInvestmentLimits(uint256 _min, uint256 _max) external onlyOwner {
        require(_min > 0, "Splitter: Min investment must be > 0");
        require(_max >= _min, "Splitter: Max investment must be >= min investment");
        minInvestment = _min;
        maxInvestment = _max;
        emit InvestmentLimitsUpdated(_min, _max);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/CyeraMiningEngine.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {MessageHashUtils} from "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 value) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
}

interface IPancakeRouterV2 {
    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;

    function getAmountsOut(uint256 amountIn, address[] calldata path)
        external
        view
        returns (uint256[] memory amounts);
}

/**
 * @title CyeraMiningEngine
 * @notice Central Investment & ROI Liquidity Execution Engine for Cyera AI.
 * 
 * EXECUTION FLOW
 * --------------
 * 1. User Investment (invest):
 *    - 70% USDT -> Directly sent to Owner Treasury Wallet (Instant USDT reserve).
 *    - 30% USDT -> Automatically swapped on PancakeSwap for CAI (Green Buy on DEX chart 🟢).
 *    - Bought CAI tokens are safely held in this engine contract.
 *
 * 2. User ROI Claim (sellPortfolio):
 *    - User claims daily mining/staking ROI via EIP-712 authorized signature.
 *    - Engine swaps CAI for USDT on PancakeSwap (Red Sell on DEX chart 🔴).
 *    - Resulting USDT is delivered directly to the user's wallet.
 */
contract CyeraMiningEngine is Ownable, ReentrancyGuard {
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    IERC20 public immutable usdt;
    IERC20 public immutable caiToken;
    IPancakeRouterV2 public immutable pancakeRouter;

    address public treasuryWallet;
    address public backendSigner;

    // EIP-712 Domain Separator constants
    bytes32 private constant CLAIM_TYPEHASH = keccak256(
        "SellPortfolio(address user,uint256 caiAmount,uint256 minUsdtOut,uint256 nonce,uint256 expiry)"
    );
    bytes32 public immutable DOMAIN_SEPARATOR;

    // Prevent nonce reuse for ROI claims
    mapping(address => mapping(uint256 => bool)) public isNonceExecuted;

    // Track total volume
    uint256 public totalInvestedUsdt;
    uint256 public totalCaiPurchased;
    uint256 public totalRoiUsdtPaid;

    // Events
    event Invested(
        address indexed user,
        uint256 totalAmountUsdt,
        uint256 indexed packageId,
        uint256 treasuryUsdt,
        uint256 liquidityUsdt,
        uint256 caiPurchased,
        uint256 timestamp
    );

    event PortfolioSold(
        address indexed user,
        uint256 caiAmountSold,
        uint256 usdtDelivered,
        uint256 indexed nonce,
        uint256 timestamp
    );

    event TreasuryWalletUpdated(address indexed previousWallet, address indexed newWallet);
    event BackendSignerUpdated(address indexed previousSigner, address indexed newSigner);

    error ZeroAddress();
    error InvalidAmount();
    error InvalidSignature();
    error SignatureExpired();
    error NonceAlreadyUsed();
    error SlippageExceeded();
    error TransferFailed();

    constructor(
        address _usdt,
        address _caiToken,
        address _pancakeRouter,
        address _treasuryWallet,
        address _backendSigner,
        address _initialOwner
    ) Ownable(_initialOwner) {
        if (
            _usdt == address(0) ||
            _caiToken == address(0) ||
            _pancakeRouter == address(0) ||
            _treasuryWallet == address(0) ||
            _backendSigner == address(0) ||
            _initialOwner == address(0)
        ) {
            revert ZeroAddress();
        }

        usdt = IERC20(_usdt);
        caiToken = IERC20(_caiToken);
        pancakeRouter = IPancakeRouterV2(_pancakeRouter);
        treasuryWallet = _treasuryWallet;
        backendSigner = _backendSigner;

        // Compute EIP-712 Domain Separator
        DOMAIN_SEPARATOR = keccak256(
            abi.encode(
                keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
                keccak256(bytes("CyeraMiningEngine")),
                keccak256(bytes("1")),
                block.chainid,
                address(this)
            )
        );

        // Pre-approve PancakeSwap router for USDT and CAI transfers
        IERC20(_usdt).approve(_pancakeRouter, type(uint256).max);
        IERC20(_caiToken).approve(_pancakeRouter, type(uint256).max);
    }

    /**
     * @notice Process user package investment (70% Treasury + 30% PancakeSwap Auto-Buy).
     * @param amountUsdt Total investment amount in USDT (18 decimals).
     * @param packageId Internal package / staking tier identifier.
     */
    function invest(uint256 amountUsdt, uint256 packageId) external nonReentrant {
        if (amountUsdt == 0) revert InvalidAmount();

        // 1. Pull USDT from user to this contract
        bool success = usdt.transferFrom(msg.sender, address(this), amountUsdt);
        if (!success) revert TransferFailed();

        // 2. Calculate 70% and 30% split
        uint256 treasuryAmount = (amountUsdt * 70) / 100;
        uint256 liquidityAmount = amountUsdt - treasuryAmount;

        // 3. Send 70% USDT directly to Owner Treasury Wallet
        success = usdt.transfer(treasuryWallet, treasuryAmount);
        if (!success) revert TransferFailed();

        // 4. Auto-Buy CAI on PancakeSwap with remaining 30% USDT (Green Buy on DEX chart)
        address[] memory path = new address[](2);
        path[0] = address(usdt);
        path[1] = address(caiToken);

        uint256 caiBefore = caiToken.balanceOf(address(this));

        pancakeRouter.swapExactTokensForTokensSupportingFeeOnTransferTokens(
            liquidityAmount,
            0, // Accept market execution price
            path,
            address(this), // Engine holds purchased CAI
            block.timestamp + 300
        );

        uint256 caiPurchased = caiToken.balanceOf(address(this)) - caiBefore;

        totalInvestedUsdt += amountUsdt;
        totalCaiPurchased += caiPurchased;

        emit Invested(
            msg.sender,
            amountUsdt,
            packageId,
            treasuryAmount,
            liquidityAmount,
            caiPurchased,
            block.timestamp
        );
    }

    /**
     * @notice Claim ROI / Working Income by selling CAI on PancakeSwap for USDT (Delivered to User).
     * @param caiAmount Amount of CAI to swap and sell on PancakeSwap.
     * @param minUsdtOut Minimum acceptable USDT to prevent front-running.
     * @param nonce Unique transaction nonce generated by backend.
     * @param expiry Expiration timestamp for the cryptographic signature.
     * @param signature Cryptographic signature from authorized backendSigner.
     */
    function sellPortfolio(
        uint256 caiAmount,
        uint256 minUsdtOut,
        uint256 nonce,
        uint256 expiry,
        bytes calldata signature
    ) external nonReentrant {
        if (caiAmount == 0) revert InvalidAmount();
        if (block.timestamp > expiry) revert SignatureExpired();
        if (isNonceExecuted[msg.sender][nonce]) revert NonceAlreadyUsed();

        // 1. Verify EIP-712 Cryptographic Signature
        bytes32 structHash = keccak256(
            abi.encode(
                CLAIM_TYPEHASH,
                msg.sender,
                caiAmount,
                minUsdtOut,
                nonce,
                expiry
            )
        );

        bytes32 digest = MessageHashUtils.toTypedDataHash(DOMAIN_SEPARATOR, structHash);
        address recoveredSigner = ECDSA.recover(digest, signature);

        if (recoveredSigner != backendSigner) revert InvalidSignature();

        // 2. Mark nonce as consumed
        isNonceExecuted[msg.sender][nonce] = true;

        // 3. Swap CAI for USDT on PancakeSwap (Red Sell on DEX chart) & deliver USDT to user
        address[] memory path = new address[](2);
        path[0] = address(caiToken);
        path[1] = address(usdt);

        uint256 userUsdtBefore = usdt.balanceOf(msg.sender);

        pancakeRouter.swapExactTokensForTokensSupportingFeeOnTransferTokens(
            caiAmount,
            minUsdtOut,
            path,
            msg.sender, // Deliver USDT directly to user
            block.timestamp + 300
        );

        uint256 usdtDelivered = usdt.balanceOf(msg.sender) - userUsdtBefore;
        totalRoiUsdtPaid += usdtDelivered;

        emit PortfolioSold(
            msg.sender,
            caiAmount,
            usdtDelivered,
            nonce,
            block.timestamp
        );
    }

    /**
     * @notice Admin update for Treasury Wallet.
     */
    function setTreasuryWallet(address _newTreasury) external onlyOwner {
        if (_newTreasury == address(0)) revert ZeroAddress();
        address old = treasuryWallet;
        treasuryWallet = _newTreasury;
        emit TreasuryWalletUpdated(old, _newTreasury);
    }

    /**
     * @notice Admin update for Backend Signer.
     */
    function setBackendSigner(address _newSigner) external onlyOwner {
        if (_newSigner == address(0)) revert ZeroAddress();
        address old = backendSigner;
        backendSigner = _newSigner;
        emit BackendSignerUpdated(old, _newSigner);
    }

    /**
     * @notice Emergency recovery for non-protocol tokens accidentally sent to contract.
     */
    function rescueTokens(address token, address to, uint256 amount) external onlyOwner {
        if (to == address(0)) revert ZeroAddress();
        IERC20(token).transfer(to, amount);
    }
}

